tasks.check:
set -o pipefail; cd "$PWD"; export PYTHONPATH=$PWD TMPDIR=/tmp; PY=/home/bcorfman/dev/freytag-forge/.venv/bin/python
test -s notes.md && cp notes.md /home/bcorfman/dev/ringer-work/door-ask-player-cap-notes.md || { echo "FAIL: notes.md missing"; exit 1; }
bad=$(git status --porcelain | awk '{print $2}' | grep -v -x -e notes.md -e pytest.out -e scripts/ringer/stage7/door_ask_player.mjs -e tests/test_door_ask_player_cap.py)
test -z "$bad" || { echo "FAIL: outside ownership: $bad"; exit 1; }
grep -q 'cap: 2' scripts/ringer/stage7/door_ask_player.mjs || { echo "FAIL: cap not 2"; exit 1; }
git diff --quiet -- frontend storygame data || { echo "FAIL: frontend/storygame/data edited"; exit 1; }
$PY -m pytest -q --no-cov -p no:cacheprovider tests/test_door_ask_player_cap.py tests/test_3c_families_offer_arm.py tests/test_3c_families_offer_probe.py > pytest.out 2>&1; rc=$?; tail -15 pytest.out; test $rc -eq 0 || exit 1
grep -q skipped pytest.out && { echo "FAIL: cap test skipped"; exit 1; }
$PY -m ruff check tests/test_door_ask_player_cap.py && $PY -m ruff format --check tests/test_door_ask_player_cap.py || exit 1
git add -A -- scripts tests; git diff --cached -- scripts tests > /home/bcorfman/dev/ringer-work/door-ask-player-cap.patch; test -s /home/bcorfman/dev/ringer-work/door-ask-player-cap.patch && echo patch-exported
